3.555884],[133.51317,33.556582],[133.515717,33.557147],[133.516752,33.557228],[133.527264,33.557313],[133.529236,33.557489],[133.529244,33.557422],[133.529477,33.557403],[133.529569,33.557022],[133.530306,33.557154],[133.530367,33.557068],[133.530668,33.557047],[133.530718,33.556829],[133.530835,33.556804],[133.530851,33.556727],[133.53248,33.55698],[133.532618,33.556394],[133.53278,33.556424],[133.532936,33.556345]]}', distance_m = 6935, elevation_gain_m = 34, course_type = 'out_and_back', surface = 'asphalt', signals_count = NULL WHERE id = '9e4a98a3-5fd5-4e8a-9d2c-6a266e3b9c39' AND name IS '柳原橋〜新月橋・北岸約2.4km往復（参考ルート）' AND geojson IS '{"type":"LineString","coordinates":[[133.5297767,33.5547799],[133.5283588,33.5545704],[133.5210238,33.554531],[133.5203287,33.5546424],[133.5183033,33.5552221],[133.5170117,33.5553387],[133.5183033,33.5552221],[133.5203287,33.5546424],[133.5210238,33.554531],[133.5283588,33.5545704],[133.5297767,33.5547799]]}' AND geojson_simplified IS '{"type":"LineString","coordinates":[[133.5297767,33.5547799],[133.5283588,33.5545704],[133.5210238,33.554531],[133.5203287,33.5546424],[133.5183033,33.5552221],[133.5170117,33.5553387],[133.5183033,33.5552221],[133.5203287,33.5546424],[133.5210238,33.554531],[133.5283588,33.5545704],[133.5297767,33.5547799]]}' AND distance_m IS 2409 AND elevation_gain_m IS 4 AND course_type IS 'out_and_back' AND surface IS 'mixed' AND signals_count IS NULL;
INSERT INTO spot_tags (spot_id, tag_id) SELECT '8058cae5-1ccf-4c50-912d-5d2177cdea3b', '96971737-d3f7-42c3-a72e-4941375b94d4' WHERE EXISTS (SELECT 1 FROM spots WHERE id = '8058cae5-1ccf-4c50-912d-5d2177cdea3b' AND lat IS 33.556345 AND lng IS 133.532936 AND description IS '高知市中心部を流れる鏡川の北岸を、柳原付近から鏡川橋まで遡って戻る約6.9kmの往復コース。堤防上には車道と分かれた遊歩道が続き、信号に止まらず走れる。ほぼ完全にフラットで、川面と筆山を眺めながらのジョグに向く。散歩やランニングの地元利用が多く、上流・下流へ足を延ばして距離を調整しやすい。' AND access IS 'とさでん交通伊野線・県庁前電停や鏡川橋電停から徒歩すぐ') AND NOT EXISTS (SELECT 1 FROM spot_tags WHERE spot_id = '8058cae5-1ccf-4c50-912d-5d2177cdea3b' AND tag_id = '96971737-d3f7-42c3-a72e-4941375b94d4');
-- kamogawa-sanjo-demachiyanagi
UPDATE spots SET lat = 35.009499, lng = 135.773946, description = '京都の街なかランの王道区間で、三条大橋から出町柳までは片道およそ2.3kmです。河川敷に下りれば信号に止められにくく、川の流れや比叡山方面の眺めを感じながら一定ペースで走れます。周辺に橋が多いため距離調整もしやすく、観光や仕事の合間の朝ランにも好相性です。ジョグからテンポ走まで幅広く対応でき、京都でまず名前が挙がる代表的なリバーサイドです。目的に応じて本数や往復回数を調整しやすい点も実用的です。', access = '京阪本線 三条駅から徒歩約3分。', updated_at = unixepoch() * 1000 WHERE id = '1a7b0af5-31bc-4857-988d-f4e1e4e2bbd2' AND lat IS 35.0097382 AND lng IS 135.7720617 AND description IS '三条大橋の北側から鴨川の東岸河川敷を上流へ進み、出町柳の賀茂大橋北側で折り返す約4.4kmの参考ルートです。橋の下を通りながら、川沿いの舗装路や土の道をつなぎます。道路沿いの歩道ではなく、河川敷へ下りて走るコースです。散歩や自転車の利用者が多いので、混雑時は速度を落とし、増水や工事の通行案内を優先してください。' AND access IS '京阪三条駅・地下鉄三条京阪駅から三条大橋へ。橋の東側から河川敷へ下り、橋の北側の園路でスタートします。';
